foreach (int requested in new[] { 2, 0, 7, 5 })
{
    try
    {
        int remaining = Remaining(stock: 5, requested: requested);
        Console.WriteLine($"Remaining: {remaining}");
    }
    catch (ArgumentOutOfRangeException)
    {
        Console.WriteLine("Quantity must be positive.");
    }
    catch (InvalidOperationException)
    {
        Console.WriteLine("Insufficient stock.");
    }
}

static int Remaining(int stock, int requested)
{
    if (requested <= 0)
    {
        throw new ArgumentOutOfRangeException(nameof(requested));
    }
    if (requested > stock)
    {
        throw new InvalidOperationException("Insufficient stock.");
    }
    return stock - requested;
}

using System.Text.Json;

string directory = Directory.CreateTempSubdirectory("nexora-json-").FullName;
try
{
    string path = Path.Combine(directory, "inventory.json");
    var original = new List<Product>
    {
        new Product("P-101", "Notebook", 12),
        new Product("P-102", "Pen", 4)
    };

    string json = JsonSerializer.Serialize(original);
    File.WriteAllText(path, json);
    string stored = File.ReadAllText(path);
    List<Product> restored = JsonSerializer.Deserialize<List<Product>>(stored)
        ?? throw new InvalidDataException("Inventory data is missing.");
    foreach (Product item in restored)
    {
        Console.WriteLine($"{item.Sku}: {item.Quantity}");
    }
}
finally
{
    Directory.Delete(directory, recursive: true);
}

record Product(string Sku, string Name, int Quantity);

Check("partial issue", expected: true, actual: CanIssue(5, 3));
Check("exact balance", expected: true, actual: CanIssue(5, 5));
Check("insufficient", expected: false, actual: CanIssue(5, 6));
Check("zero quantity", expected: false, actual: CanIssue(5, 0));

static bool CanIssue(int stock, int requested)
{
    return requested > 0 && requested <= stock;
}

static void Check(string name, bool expected, bool actual)
{
    if (actual != expected)
    {
        throw new InvalidOperationException($"{name}: expected {expected}, got {actual}");
    }
    Console.WriteLine($"PASS: {name}");
}
